@st.cache_data(show_spinner=False)
def process_wintax_v451_cached(file_bytes: bytes, file_name: str, circuit_hint: str, _ver: str = "4.9.2") -> dict:
    raw_df = read_uploaded_csv_cached(file_bytes, file_name)
    return tse.process_wintax_Telemetry(raw_df, circuit_hint=circuit_hint)


def process_wintax_safe(file_bytes: bytes, file_name: str, circuit_hint: str) -> dict:
    res = process_wintax_v451_cached(file_bytes, file_name, circuit_hint, _ver="4.9.2")
    if "df" not in res or "Combined_G" not in res["df"].columns or "Actual_Road_Steer_deg" not in res["df"].columns:
        raw_df = read_uploaded_csv_cached(file_bytes, file_name)
        res = tse.process_wintax_Telemetry(raw_df, circuit_hint=circuit_hint)
    return res



@st.cache_data(show_spinner=False)
def read_uploaded_csv_cached(file_bytes: bytes, file_name: str) -> pd.DataFrame:
    """대용량 WinTAX/타임지 CSV 재파싱 방지를 위한 메모리 캐시 로더."""
    try:
        df = pd.read_csv(io.BytesIO(file_bytes))
        if len(df.columns) < 2:
            df = pd.read_csv(io.BytesIO(file_bytes), sep=';')
        return df
    except Exception:
        return pd.read_csv(io.BytesIO(file_bytes), sep=';')


@st.cache_data(show_spinner=False)
def read_uploaded_excel_cached(file_bytes: bytes, file_name: str) -> pd.DataFrame:
    return pd.read_excel(io.BytesIO(file_bytes))


def ensure_expected_headers(df: pd.DataFrame, required_keywords: list[str]) -> pd.DataFrame:
    """구글 시트 상단에 제목 행이 있어 실제 컬럼 헤더가 아래 줄에 있을 때 자동 보정."""
    if df is None or df.empty:
        return df
    col_str = ' '.join(str(c).upper() for c in df.columns)
    if all(k.upper() in col_str for k in required_keywords):
        return df
    for r_idx in range(min(5, len(df))):
        row_vals = [str(v).strip() if pd.notna(v) else '' for v in df.iloc[r_idx].tolist()]
        joined = ' '.join(v.upper() for v in row_vals)
        if all(k.upper() in joined for k in required_keywords):
            seen: dict[str, int] = {}
            new_cols: list[str] = []
            for c_i, name in enumerate(row_vals):
                clean_n = name if name else f'Unnamed: {c_i}'
                if clean_n in seen:
                    seen[clean_n] += 1
                    new_cols.append(f'{clean_n}.{seen[clean_n]}')
                else:
                    seen[clean_n] = 0
                    new_cols.append(clean_n)
            out = df.iloc[r_idx + 1 :].reset_index(drop=True).copy()
            out.columns = new_cols
            return out
    return df


def safe_int(val, default: int) -> int:
    if val is None or pd.isna(val):
        return default
    try:
        return int(float(str(val).strip()))
    except (ValueError, TypeError):
        return default


def safe_float(val, default: float) -> float:
    if val is None or pd.isna(val):
        return default
    try:
        return float(str(val).replace('%', '').strip())
    except (ValueError, TypeError):
        return default

