            # [4] 100% 실측 DB 기반 4대 인터랙티브 분석 차트 (가짜 하드코딩 차트 완전 교체!)
            # ==================================================================
            ch_r1c1, ch_r1c2 = st.columns(2)

            with ch_r1c1:
                laps_arr = list(range(0, 13))
                g87_plot = d87["grid"] if d87["grid"] > 0 else d87["finish_num"]
                g97_plot = d97["grid"] if d97["grid"] > 0 else d97["finish_num"]
                f87_plot = d87["finish_num"]
                f97_plot = d97["finish_num"]

                def _make_pos_trace(g_p: int, f_p: int, inc_lap: int | None) -> list[int]:
                    if inc_lap is not None and 1 <= inc_lap <= 11 and f_p > g_p:
                        # Realistic drop right at the incident lap!
                        pre = [int(round(g_p - (g_p - max(1, g_p - 1)) * (lp / max(1, inc_lap)))) for lp in range(0, inc_lap)]
                        post = [f_p for _ in range(inc_lap, 13)]
                        return (pre + post)[:13]
                    return [int(round(g_p + (f_p - g_p) * (lp / 12.0))) for lp in laps_arr]

                c87_y = _make_pos_trace(g87_plot, f87_plot, d87["incident_lap_num"])
