                existing_ids = {str(x["Tire_ID"]).strip() for x in seed_rows}
                # Merge any new Tire IDs spotted in live `TIRE_ANALYSIS_87` / `TIRE_ANALYSIS_97` sheets!
                for c_tag, p_bundle in [("#87", parsed_87), ("#97", parsed_97)]:
                    rdf_live = p_bundle.get("runs_df", pd.DataFrame())
