            active_parsed = parsed_87 if "#87 박준의" in car_view else parsed_97
            runs_df = active_parsed["runs_df"].copy()
            meta_t = active_parsed["meta"]

            if "#87 vs #97" in car_view:
                r87 = parsed_87["runs_df"].copy()
                r97 = parsed_97["runs_df"].copy()
