            pred_r_str = f"{meta_t['r_predicted_cold']:.2f} Bar" if pd.notna(meta_t["r_predicted_cold"]) else "-"
            k5.metric("시트 추천 Front Cold", pred_f_str, f"ΔT {meta_t['delta_track_temp']:+.0f}°C 반영")
            k6.metric("시트 추천 Rear Cold", pred_r_str, f"Track Sev {meta_t['track_sev']:.1f}")

            flt_df = runs_df.copy()
