            if sel_ses_filter != "전체 (All)" and "SESSION" in flt_df.columns:
                flt_df = flt_df[flt_df["SESSION"] == sel_ses_filter]

            if not flt_df.empty:
                st.markdown("#### 📋 세션별 타이어 운용·압력·히트사이클 요약 테이블")
                disp_cols = [c for c in [
                    "DATE", "CIRCUIT", "SESSION", "LAPS", "CAR NO.",
                    "FL ID", "FR ID", "RL ID", "RR ID",
                    "AIR TEMP (°C)", "TRACK TEMP (°C)",
                    "Cold FL (Bar)", "Cold FR (Bar)", "Cold RL (Bar)", "Cold RR (Bar)",
                    "Hot FL (Bar)", "Hot FR (Bar)", "Hot RL (Bar)", "Hot RR (Bar)",
                    "ΔP FL", "ΔP FR", "ΔP RL", "ΔP RR", "Target Error",
                    "SWAP / PUSH OUT", "Heat Cycle", "Best Lap (Session)", "Notes"
                ] if c in flt_df.columns]
                st.dataframe(flt_df[disp_cols], use_container_width=True, hide_index=True)

                col_g1, col_g2 = st.columns([1.15, 1.0])
