                    temp_rows = flt_df[flt_df["FL_Mid_C"].notna()] if "FL_Mid_C" in flt_df.columns else pd.DataFrame()
                    if not temp_rows.empty:
                        row_opts = [f"{idx}: {r.get('DATE','')} | {r.get('LAPS','')} ({r.get('CAR NO.','')})" for idx, r in temp_rows.iterrows()]
                        picked_lbl = st.selectbox("온도 계측 런 선택", row_opts, index=len(row_opts) - 1, key="m6_temp_row")
                        picked_idx = int(picked_lbl.split(":")[0])
                        tr = temp_rows.loc[picked_idx]

