            m_hfr = bc2.number_input("피트인 실측 Hot FR", value=2.34, step=0.01, format="%.2f", key="m6_bhfr")
            m_hrl = bc3.number_input("피트인 실측 Hot RL", value=2.24, step=0.01, format="%.2f", key="m6_bhrl")
            m_hrr = bc4.number_input("피트인 실측 Hot RR", value=2.22, step=0.01, format="%.2f", key="m6_bhrr")
