                fig_press.add_hline(y=t_hot_ref + 0.15, line_dash="dot", line_color="#ff4757", annotation_text="Over-pressure Warning")
                fig_press.update_layout(title=f"<b>{selected_driver} — {selected_circuit} 랩별 열간 공기압 예측 곡선</b>",
                                        xaxis_title="Laps", yaxis_title="Hot Pressure (Bar)", hovermode="x unified", template="plotly_dark", height=390)
                st.plotly_chart(fig_press, use_container_width=True)

