    def _render_wrapped_html_table(df_in: pd.DataFrame) -> str:
        """긴 한국어 공략 문구가 가로로 잘리지(`...`) 않도록 줄바꿈 완비 다크테마 테이블 렌더링."""
        if df_in is None or df_in.empty:
            return ""
        ths = "".join(
            f"<th style='background:#1e293b;color:#f8fafc;padding:8px 10px;text-align:left;border-bottom:2px solid #38bdf8;font-size:0.86rem;'>{c}</th>"
            for c in df_in.columns
        )
        trs = []
        for idx_r, row_r in df_in.iterrows():
            bg = "#131c2e" if ("우리 팀" in str(row_r.iloc[0]) or "#87" in str(row_r.iloc[0]) or "#97" in str(row_r.iloc[0])) else ("#0f172a" if idx_r % 2 == 0 else "#161f30")
            tds = "".join(
                f"<td style='padding:8px 10px;color:#e2e8f0;border-bottom:1px solid #263248;font-size:0.85rem;line-height:1.45;vertical-align:top;word-break:keep-all;'>{v}</td>"
                for v in row_r.values
            )
            trs.append(f"<tr style='background:{bg};'>{tds}</tr>")
        return f"<div style='overflow-x:auto;border:1px solid #334155;border-radius:8px;margin-bottom:12px;'><table style='width:100%;border-collapse:collapse;'><thead><tr>{ths}</tr></thead><tbody>{''.join(trs)}</tbody></table></div>"

